#!/usr/bin/env python3
"""Endpoint coverage at the frozen base; Python 3 stdlib, no Lean.
Run from any cwd: python3 docs/audits/direction-tools/endpoint/measure.py --check
Regenerate: same command without --check.
Refresh external catalog: --eest /path/to/shallow/execution-spec-tests
Reproduce external source: git clone --depth 1 https://github.com/ethereum/execution-spec-tests.git DIR;
git -C DIR fetch --depth 1 origin <catalog.commit>; git -C DIR checkout --detach FETCH_HEAD.
The catalog counts test FUNCTION TEMPLATES, not pytest parameter expansions or fixture vectors.
"""
import argparse, ast, collections, hashlib, importlib.util, json, pathlib, re, subprocess, sys
sys.dont_write_bytecode = True
OUT = pathlib.Path(__file__).resolve().parent
ROOT = OUT.parents[3]
BASE = "d6fd95f0886775d7c286813fa9b993a40ba7a777"
def git(*a): return subprocess.check_output(["git", "-C", str(ROOT), *a])
CACHE = {}
def read(p):
    if p not in CACHE: CACHE[p] = git("show", BASE + ":" + p).decode()
    return CACHE[p]
def load(p): return json.loads(read(p))
def digest(b): return hashlib.sha256(b).hexdigest()
def at(p, needle):
    s = read(p); assert needle in s, (p, needle)
    return {"path": p, "line": s[:s.index(needle)].count("\n") + 1, "anchor": needle}
def pct(n,d): return round(100*n/d, 4) if d else None
def dump(v): return json.dumps(v, indent=2, sort_keys=True) + "\n"
def external(path):
    pin = subprocess.check_output(["git", "-C", str(path), "rev-parse", "HEAD"], text=True).strip()
    files=[]
    for f in sorted((path / "tests").rglob("*.py")):
        raw=f.read_bytes(); tree=ast.parse(raw)
        names=[{"name": n.name, "line": n.lineno} for n in ast.walk(tree)
               if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef)) and n.name.startswith("test_")]
        files.append({"path": str(f.relative_to(path)), "sha256": digest(raw), "templates": names})
    return {"repository": "https://github.com/ethereum/execution-spec-tests", "commit": pin,
            "unit": "Python test_* function template; includes every fork and benchmark under tests/; not expanded fixtures",
            "files": files}
def measure(eest):
    paths = sorted(git("ls-tree", "-r", "--name-only", BASE).decode().splitlines())
    # Reuse the committed marker classifier; explicitly override Imported.lean as handwritten.
    spec=importlib.util.spec_from_file_location("census", ROOT/"docs/audits/direction-tools/census/metrics.py")
    census=importlib.util.module_from_spec(spec); spec.loader.exec_module(census)
    CACHE.update(census.blobs({p:b for p,b in census.tree(BASE).items() if p.endswith(".lean")}))
    counts=collections.defaultdict(collections.Counter); public=[]; lowering=[]
    for p in paths:
        if not p.endswith(".lean"): continue
        text=read(p)
        cat=census.category(p,text)
        if p=="Solidity/Corpus/Imported.lean": cat="unmarked"
        total=len(text.splitlines()); gen=0
        if cat=="mixed_generated_blocks":
            inside=False
            for line in text.splitlines():
                if line.startswith("-- BEGIN generated by "): inside=True
                elif line.startswith("-- END generated by "): inside=False
                elif inside: gen+=1
        elif cat not in ("unmarked","import_only_unknown"): gen=total
        area=p.split("/")[1] if p.startswith("Solidity/") else "outside-Solidity"
        for k in ("ALL", area):
            counts[k].update(files=1,physical_lines=total,detected_generated_lines=gen,
                unmarked_lines=total-gen-(total if cat=="import_only_unknown" else 0),
                unknown_import_only_lines=total if cat=="import_only_unknown" else 0)
        if "Chain" in p or "Agreement" in p:
            counts["chain-agreement-name-candidates"].update(files=1,physical_lines=total,detected_generated_lines=gen,unmarked_lines=total-gen)
        clean=census.clean(text) if re.search(r"\b(PublicCorrectness|Stages|lowerLoops|uncheckStmts)\b",text) else ""
        for n,line in enumerate(clean.splitlines(),1):
            if re.search(r"\bPublicCorrectness\b|\bStages\b",line):
                public.append({"path":p,"line":n,"code":line.strip()[:240]})
            if re.search(r"\b(lowerLoops|uncheckStmts)\b",line):
                lowering.append({"path":p,"line":n,"code":line.strip()[:240]})
    rows=[]
    for line in read("tests/solkey/expected.tsv").splitlines():
        group,suite,name,status,note,evidence=line.split("\t")
        rows.append(dict(group=group,suite=suite,name=name,status=status,note=note,evidence=evidence))
    suite=[r for r in rows if r["suite"]=="TestSuite"]
    others=[r for r in rows if r["suite"]!="TestSuite"]
    statuses=lambda rs:dict(sorted(collections.Counter(r["status"] for r in rs).items()))
    # Resolve every derived/proved row to a tracked theorem-bearing module, retaining names verbatim.
    for r in rows:
        if r["status"] in ("derived","proved"):
            ps=re.findall(r"Solidity/[^` )]+\.lean",r["evidence"])
            if r["status"]=="proved" and r["group"]=="net":
                ps=["Solidity/"+re.search(r"`([^`]+\.lean)`",r["evidence"]).group(1)]
                r["theorem"]=re.findall(r"`([^`]+)`",r["evidence"])[1]
                assert "theorem "+r["theorem"].split(".")[-1] in read(ps[0]),r
            elif r["status"]=="proved":
                ps=["Solidity/Corpus/"+r["suite"]+".lean"]
                assert "theorem "+r["name"] in read(ps[0]),r
                r["theorem"]="Solidity.Corpus."+r["suite"]+"."+r["name"]
            else: r["theorem"]="Solkey.TestSuite."+r["name"]+".proved"
            r["proof_modules"]=ps
            assert ps and all(p in paths for p in ps),r
    key=read("Solidity/Calculus/KeyTaclets.lean")
    taclets=re.findall(r"^  \| (\w+)",key.split("inductive KeyTaclet where")[1].split("deriving")[0],re.M)
    shapes=read("Solidity/Calculus/RuleShapes.lean")
    unclaimed=re.findall(r"\.([A-Za-z_][A-Za-z_0-9]*)",shapes.split("def unclaimedTaclets : List KeyTaclet :=")[1].split("/-")[0])
    pending=re.findall(r"\.([A-Za-z_][A-Za-z_0-9]*)",shapes.split("def migrationPendingTaclets : List KeyTaclet :=")[1].split("/-")[0])
    assert set(unclaimed)<=set(taclets) and set(pending)<=set(taclets)
    claimed=[t for t in taclets if t not in unclaimed+pending]
    snapshot=load("tests/upstream/snapshot.json")
    sem={r["path"]:r for r in snapshot["files"] if "/semanticTests/" in r["path"] and r["path"].endswith(".sol")}
    upstream=load("tests/upstream/results/results.json")
    results={r["path"]:r for r in upstream["results"] if r["path"] in sem}
    assert set(results)==set(sem)
    semantic_rows=[dict(path=p,sha256=sem[p]["sha256"],stage=results[p]["stage"],status=results[p]["status"],
        kernel_source_to_bytes=False) for p in sorted(sem)]
    stagecounts=collections.Counter(r["stage"]+":"+r["status"] for r in results.values())
    ntemplates=sum(len(f["templates"]) for f in eest["files"])
    refs=load("docs/audits/direction-tools/README-results.json")
    pass_size=refs["subsystems"]["lowering"]["metrics"]["lines"]
    kevm=next(r for r in refs["references"] if r.get("project")=="KEVM") if isinstance(refs["references"],list) else None
    chain=[
      dict(stage="SolKey obligation to intrinsic validity",status="proved in pinned source",theorem="Solidity.Proves.fmlValid",citation=at("Solidity/Calculus/Sound.lean","theorem Proves.fmlValid")),
      dict(stage="source admission",status="interface; a full accepted-source producer still required",citation=at("Solidity/Roadmap/Contracts.lean","structure CheckedFrontend")),
      dict(stage="actual loop/unchecked lowering to intrinsic",status="missing general semantic preservation for emitted programs",citation=at("Solidity/Syntax/Elab/Lower.lean","def lowerLoops"),other=at("Solidity/Syntax/Elab/Lower.lean","partial def uncheckStmts")),
      dict(stage="source-world lowering certificate",status="interface, not a concrete compiler instance",citation=at("Solidity/Roadmap/Contracts.lean","structure Lowering")),
      dict(stage="checked intrinsic compilation",status="proved conditional on Compilation.Input; includes core and memory branches",theorem="Solidity.Main.compiler_checked",citation=at("Solidity/Theorems.lean","theorem compiler_checked")),
      dict(stage="instruction assembly to deployed bytes",status="Execution certificate is a supplied stage; not provided by compiler_checked",citation=at("Solidity/Roadmap/Contracts.lean","structure Execution")),
      dict(stage="composition of supplied stages",status="proved conditionally; concrete stages/tables still inputs",theorem="Solidity.Yul.Composition.CorrectnessInstances.Stages.publicCorrectness",citation=at("Solidity/Yul/Composition/CorrectnessPublic.lean","theorem Stages.publicCorrectness")),
      dict(stage="environment, deployment table, hashes, state export",status="nine residual producer obligations",citation=at("Solidity/Yul/Composition/CorrectnessPublic.lean","structure PublicBoundary")),
      dict(stage="approved source/EVM and real Keccak",status="separate final conjuncts, not inferred from toy PublicCorrectness",citation=at("Solidity/Roadmap/Contracts.lean","def EvmSpec.Approved"))]
    frag=read("Solidity/Evm/Compile.lean")
    features=[]
    for label,start,stop,description in [
      ("statements","def inFrag {","/-- A block of the fragment.","Core: assignments, locals/storage aliases, push/pop/delete, conditionals/block, require/assert/revert, bounded-normal loop and scalar internal call subject to guards. Not a Solidity-source acceptance theorem."),
      ("expressions/storage","def spathIn {","/-- The storage location", "Primitive expressions with recursive guards; map keys uint; offsets/fixed array sizes fit W; fragile aliases tracked. Core excludes memory reads/length, modular/hash expressions."),
      ("calls","def argsIn {","/-- An alias bound", "Core: scalar args and zero/single scalar return. Reject reference args and multi/reference returns. Payment refusal remains observable in the legacy compiler theorem."),
      ("types","def simpleIn","mutual", "Simple values and operation-specific primitive type restrictions; retain exact predicate below rather than claiming all Solidity scalar types.")]:
        a=frag.index(start); b=frag.index(stop,a)
        features.append(dict(category=label,description=description,citation=at("Solidity/Evm/Compile.lean",start),predicate=frag[a:b].strip()))
    compilation=read("Solidity/Evm/Compiler.lean")
    branchtext=compilation.split("inductive Compilation")[1].split("private def compileCopies")[0]
    branches=re.findall(r"^  \| (\w+)",branchtext,re.M)
    derived=sum(r["status"]=="derived" for r in suite)
    refuted=sum(r["status"]=="refuted" for r in suite)
    proved=sum(r["status"]=="proved" for r in others)
    summary={
      "schema":1,"base":BASE,"scope":"docs/audits/direction-tools/endpoint/**; code read only",
      "command":"python3 docs/audits/direction-tools/endpoint/measure.py --check",
      "counting_boundary":"Pinned committed statements and reports, not fresh kernel validation. Units remain separate: obligations, taclets, semantic fixture files, EEST function templates. Never add their denominators into a percentage.",
      "endpoints":{
        "a": {"product":"SolKey-compatible proof core","denominators":{"TestSuite_obligations":len(suite),"program_taclets":len(taclets),"additional_corpus_rows":len(others)},
          "numerators":{"TestSuite_derived":derived,"TestSuite_refuted_negative_controls":refuted,"claimed_taclets":len(claimed),"additional_proved_model_examples":proved},
          "percent_TestSuite_derived":pct(derived,len(suite)),"percent_taclets_claimed":pct(len(claimed),len(taclets)),
          "other_statuses":{"TestSuite":statuses(suite),"additional_corpus":statuses(others)},
          "theorems":["Solkey.TestSuite.<function>.proved (exact row names in solkey.json)","Solidity.Proves.fmlValid","Solidity.Stmt.sound","Solidity.taclets_partitioned"],
          "verdict":"justified","reason":"Substantial checked intrinsic proof endpoint already exists. Claimed taclets and model proofs measure the core, not Java parser equivalence or production semantics. Unclaimed architectural rules remain denominator members; refutations do not count as positive coverage."},
        "b": {"product":"verified accepted-fragment compiler","denominator_definition":"Tagged solc semantic fixture files and SolKey corpus obligations restricted by a concrete source-to-deployed-byte theorem's acceptance predicate. No non-toy source predicate is established at this base.",
          "denominator":{"certified_source_fragment_solc_files":0,"certified_source_fragment_SolKey_rows":0,"unrestricted_solc_files":len(sem),"unrestricted_SolKey_rows":len(rows)},
          "numerator":{"kernel_source_to_deployed_bytes_solc_files":0,"kernel_source_to_deployed_bytes_SolKey_rows":0},
          "restricted_fraction":None,"percent_all_semanticTests_with_certified_acceptance":0,
          "fraction_explanation":"0/0 restricted fraction is undefined, not 100%. Zero percent is certified source acceptance among all pinned semanticTests; it is NOT an estimate of intrinsic compiler syntactic acceptance. That latter percentage requires a source-to-intrinsic producer and successful fragment witnesses per file.",
          "intrinsic_theorem":"Solidity.Main.compiler_checked","intrinsic_compilation_branches":branches,
          "features":features,"chain":chain,
          "residual_PublicBoundary_fields":re.findall(r"^  (\w+) :",read("Solidity/Yul/Composition/CorrectnessPublic.lean").split("structure PublicBoundary")[1].split("/-- Construct")[0],re.M),
          "verdict":"wrong-direction","reason":"Further transport expansion without producing source acceptance, deployed bytes and boundary evidence does not increase the product's certified fixture numerator. Existing intrinsic and conditional composition proofs remain useful; zero certified fixtures is not zero theorem value."},
        "c": {"product":"production Solidity/EVM conformance","denominators":{"solc_semantic_fixture_files":len(sem),"Ethereum_execution_spec_function_templates":ntemplates},
          "pins":{"solc":snapshot["commit"],"Ethereum_execution_spec_tests":eest["commit"]},
          "numerators":{"kernel_source_to_deployed_bytes_solc_files":0,"kernel_EEST_templates":0,"reported_working_scalar_interpreter_solc_files":stagecounts["lean-runtime:working"],"reported_broken_scalar_interpreter_solc_files":stagecounts["lean-runtime:broken"],"reported_blocked_solc_files":sum(v for k,v in stagecounts.items() if k.endswith(":blocked")),"EEST_templates_with_identified_adapter":0},
          "solc_stage_counts":dict(stagecounts),"working_scalar_interpreter_percent":pct(stagecounts["lean-runtime:working"],len(sem)),
          "nothing_category":"Blocked solc files have no successful adapted runtime check in this report; broken files have attempted checks. No EEST adapter or linked proof identified. This is not a claim that no isolated hand-written examples share their features.",
          "verdict":"wrong-direction","reason":"Interpreter vectors do not measure deployed bytecode, fork/gas/log/precompile or transaction conformance. This product needs executable test adapters plus a concrete approved EVM instance; more model-only examples cannot supply that coverage.",
          "external_test_boundary":upstream["metadata"]["scope"]}},
      "remaining_work_estimates":{
        "method":"Planning scenarios in additional handwritten-equivalent lines, NOT measured missing LOC, deletion budgets, person-time or statistical forecasts. Calibrated to existing reference scopes; generated fixtures excluded. Reuse could reduce them; full production proof effort can exceed them.",
        "reference_pass_pair":{"paths":["cfrontend/Cshmgen.v","cfrontend/Cshmgenproof.v","cfrontend/Cminorgen.v","cfrontend/Cminorgenproof.v"],"lines":pass_size,"generated_lines":refs["subsystems"]["lowering"]["metrics"]["generated_lines"],"source":"docs/audits/direction-tools/README-results.json#subsystems.lowering","commit":load("docs/audits/direction-tools/references/pins.json")["CompCert"]},
        "a":{"additional_lines_range":[pass_size,3*pass_size],"basis":"1-3 CompCert pass-pair units for correspondence closure, exact outstanding obligation ports and frontend/strategy parity. Not 35 independent soundness proofs: many unclaimed taclets are architectural normalization differences.","deliverable":"Close or explicitly distinguish every remaining corpus obligation and taclet; retain negative controls and current soundness."},
        "b":{"additional_lines_range":[3*pass_size,8*pass_size],"basis":"3-8 pass-pair units for certified admission/lowering, executable assembly linkage, and deployment/hash/state-export producers on a deliberately small fragment.","deliverable":"Non-toy source acceptance predicate, emitted bytes, complete boundary evidence and per-fixture acceptance witnesses."},
        "c":{"additional_lines_range":[refs["subsystems"]["backend"]["metrics"]["lines"],3*refs["subsystems"]["backend"]["metrics"]["lines"]],"basis":"1-3 complete multi-target CompCert backend portfolios as a broad integration/proof planning scale; production Solidity includes frontend, ABI, storage, calls, forks and harness work absent from a single pass. This is a scenario, not a comparable subsystem efficiency ratio.","deliverable":"All pinned semantic fixtures plus all EEST templates adapted with fork/gas/log/precompile checks and approved byte semantics; refresh to maintained pins before claiming current production support."}},
      "generated_split":dict(counts),
      "generated_method":"Reused census marker classifier, correcting Corpus/Imported.lean to handwritten per check-corpus.sh. Unmarked is not proven handwritten. Chain/agreement names grouped as candidates without treating names as generator evidence.",
      "inventory_reuse":{p:{"exists":p in paths,"sha256":digest(read(p).encode()) if p in paths else None} for p in ["docs/audits/direction.md","docs/audits/architecture-tools/timing-sample.tsv","docs/audits/proof-coverage-tools/theorem_census.py","docs/audits/build-speed.md","scripts/build-measure.py","scripts/differential/README.md","scripts/bench/README.md","scripts/check-corpus.sh","tests/upstream/results/summary.json"]},
      "waits":[{"item":"va3 differential/vu1 bench","state":"absent on pinned base; used committed upstream report instead"},{"item":"matched source-to-bytes timing","state":"no such endpoint measured; historical module timing is not a substitute"}],
      "limitations":["No Lean build, elaboration or Lean server used; kernel-checked labels describe pinned proof artifacts and trust gates, not fresh checking.","EEST denominator is test function templates at an independently pinned checkout, not expanded pytest/fixture case count; cannot compare its size to solc fixture-file count.","No executable syntactic acceptance percentage for the union of intrinsic memory/compiler predicates is asserted; it is not a source accepted fragment.","The general source-to-bytes gap is established by theorem/interface inspection and the public-boundary candidate index, not an undecidable proof of theorem nonexistence.","Frozen solc/SolKey snapshots differ from first-round reference portfolio pins; coverage uses corpus pins, calibration uses its cited reference pin."]}
    return {"summary.json":summary,"solkey.json":{"rows":rows,"taclets":{"claimed":claimed,"unclaimed":unclaimed,"pending":pending}},"semantic.json":semantic_rows,
            "boundary-index.json":{"public_correctness_or_stages_mentions":public,"lowering_mentions":lowering}}
def main():
    ap=argparse.ArgumentParser(); ap.add_argument("--check",action="store_true"); ap.add_argument("--eest",type=pathlib.Path); a=ap.parse_args()
    eest=external(a.eest) if a.eest else json.loads((OUT/"eest.json").read_text())
    products=measure(eest)
    if a.eest: products["eest.json"]=eest
    for name,value in products.items():
        content=dump(value); assert len(content.encode())<1000000,name
        if a.check: assert (OUT/name).read_text()==content,"stale: "+name
        else: (OUT/name).write_text(content)
    print("endpoint audit: PASS; "+", ".join(products))
if __name__=="__main__": main()
